102	const vimReducer = (state: VimState, action: VimAction): VimState => {
103	  switch (action.type) {
104	    case 'SET_MODE':
105	      return { ...state, mode: action.mode };
106	
107	    case 'SET_COUNT':
108	      return { ...state, count: action.count };
109	
110	    case 'INCREMENT_COUNT':
111	      return { ...state, count: state.count * DIGIT_MULTIPLIER + action.digit };
