113	    case 'CLEAR_COUNT':
114	      return { ...state, count: 0 };
115	
116	    case 'SET_PENDING_OPERATOR':
117	      return { ...state, pendingOperator: action.operator };
118	
119	    case 'SET_LAST_COMMAND':
120	      return { ...state, lastCommand: action.command };
121	
122	    case 'CLEAR_PENDING_STATES':
123	      return {
124	        ...state,
